def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    def amount_value(token):
        if not token or any(c < "0" or c > "9" for c in token):
            return None
        # Convert in chunks to support arbitrarily long decimal strings.
        value = 0
        for start in range(0, len(token), 9):
            chunk = token[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        verb = parts[0]
        success = False

        if verb == "undo" and len(parts) == 1:
            if history:
                action = history.pop()
                kind = action[0]
                if kind == "open":
                    account = action[1]
                    del balances[account]
                    frozen.discard(account)
                elif kind == "deposit":
                    balances[action[1]] -= action[2]
                elif kind == "withdraw":
                    balances[action[1]] += action[2]
                elif kind == "transfer":
                    balances[action[1]] += action[3]
                    balances[action[2]] -= action[3]
                elif kind == "freeze":
                    frozen.remove(action[1])
                else:
                    frozen.add(action[1])
                success = True

        elif verb in ("open", "deposit", "withdraw") and len(parts) == 3:
            account, token = parts[1], parts[2]
            amount = amount_value(token)
            if account and amount is not None:
                if verb == "open":
                    if account not in balances:
                        balances[account] = amount
                        history.append(("open", account))
                        success = True
                elif verb == "deposit":
                    if amount > 0 and account in balances:
                        balances[account] += amount
                        history.append(("deposit", account, amount))
                        success = True
                elif (amount > 0 and account in balances
                      and account not in frozen and balances[account] >= amount):
                    balances[account] -= amount
                    history.append(("withdraw", account, amount))
                    success = True

        elif verb == "transfer" and len(parts) == 4:
            source, destination, token = parts[1], parts[2], parts[3]
            amount = amount_value(token)
            if (source and destination and amount is not None and amount > 0
                    and source != destination and source in balances
                    and destination in balances and source not in frozen
                    and balances[source] >= amount):
                balances[source] -= amount
                balances[destination] += amount
                history.append(("transfer", source, destination, amount))
                success = True

        elif verb in ("freeze", "unfreeze") and len(parts) == 2:
            account = parts[1]
            if account and account in balances:
                if verb == "freeze" and account not in frozen:
                    frozen.add(account)
                    history.append(("freeze", account))
                    success = True
                elif verb == "unfreeze" and account in frozen:
                    frozen.remove(account)
                    history.append(("unfreeze", account))
                    success = True

        if not success:
            rejected.append(index)

    return balances, rejected
